let billable = tobool('{BillableOnly}');
let score = todouble('{AnomalyScore}');
let series =
    Usage
    | where TimeGenerated {Lookback}
    | where billable == false or IsBillable == true
    | summarize MB = sum(Quantity) by bin(TimeGenerated, 1h)
    | order by TimeGenerated asc
    | summarize Times = make_list(TimeGenerated), Values = make_list(MB);
series
| extend (Anomalies, AnomalyScore, Baseline) = series_decompose_anomalies(Values, score, -1, 'linefit')
| mv-expand TimeGenerated = Times to typeof(datetime), MB = Values to typeof(double), Baseline to typeof(double), Anomalies to typeof(long), AnomalyScore to typeof(double)
| project TimeGenerated, MB, Baseline, AnomalyScore, Anomalies
| order by TimeGenerated asc
| render timechart

let billable = tobool('{BillableOnly}');
let score = todouble('{AnomalyScore}');
let series =
    Usage
    | where TimeGenerated {Lookback}
    | where billable == false or IsBillable == true
    | summarize MB = sum(Quantity) by bin(TimeGenerated, 1h)
    | order by TimeGenerated asc
    | summarize Times = make_list(TimeGenerated), Values = make_list(MB);
series
| extend (Anomalies, AnomalyScore, Baseline) = series_decompose_anomalies(Values, score, -1, 'linefit')
| mv-expand TimeGenerated = Times to typeof(datetime), MB = Values to typeof(double), Baseline to typeof(double), Anomalies to typeof(long), AnomalyScore to typeof(double)
| where Anomalies != 0
| extend Direction = case(Anomalies == 1, 'Increase', Anomalies == -1, 'Decrease', 'None')
| project TimeGenerated, Direction, MB, Baseline, AnomalyScore
| order by TimeGenerated desc

let billable = tobool('{BillableOnly}');
let current = Usage | where TimeGenerated > ago(1h) | where billable == false or IsBillable == true | summarize CurrentMB = sum(Quantity);
let baseline = Usage | where TimeGenerated between (ago(8d) .. ago(1h)) | where billable == false or IsBillable == true | summarize HourlyMB = sum(Quantity) by bin(TimeGenerated, 1h) | summarize BaselineMB = avg(HourlyMB);
current
| extend BaselineMB = toreal(toscalar(baseline))
| extend SpikeRatio = iif(BaselineMB == 0.0, 0.0, CurrentMB / BaselineMB)
| project CurrentMB, BaselineMB, SpikeRatio

let billable = tobool('{BillableOnly}');
let now_ = now();
let monthStart = startofmonth(now_);
let nextMonth = startofmonth(datetime_add('month', 1, now_));
let hoursInMonth = (nextMonth - monthStart) / 1h;
let hoursElapsed = (now_ - monthStart) / 1h;
let hoursRemaining = hoursInMonth - hoursElapsed;
let mtdMB = toscalar(
    Usage
    | where TimeGenerated >= monthStart
    | where billable == false or IsBillable == true
    | summarize sum(Quantity));
let last24Velocity = toscalar(
    Usage
    | where TimeGenerated > ago(24h)
    | where billable == false or IsBillable == true
    | summarize MB = sum(Quantity)
    | extend VelocityMBph = MB / 24.0
    | project VelocityMBph);
let last1Velocity = toscalar(
    Usage
    | where TimeGenerated > ago(1h)
    | where billable == false or IsBillable == true
    | summarize VelocityMBph = sum(Quantity));
let mtdGB = mtdMB / 1024.0;
let proj24GB = (mtdMB + (last24Velocity * hoursRemaining)) / 1024.0;
let proj1GB  = (mtdMB + (last1Velocity  * hoursRemaining)) / 1024.0;
print
    MonthToDateGB = mtdGB,
    HoursElapsed = hoursElapsed,
    HoursRemaining = hoursRemaining,
    Last24hVelocityMBph = last24Velocity,
    Last1hVelocityMBph = last1Velocity,
    ProjectedEoM_From24h_GB = proj24GB,
    ProjectedEoM_From1h_GB = proj1GB,
    DeltaGB_1h_vs_24h = proj1GB - proj24GB

let billable = tobool('{BillableOnly}');
let now_ = now();
let monthStart = startofmonth(now_);
let nextMonth = startofmonth(datetime_add('month', 1, now_));
let hoursInMonth = (nextMonth - monthStart) / 1h;
let hoursElapsed = (now_ - monthStart) / 1h;
let hoursRemaining = hoursInMonth - hoursElapsed;
let mtdMB = toscalar(
    Usage
    | where TimeGenerated >= monthStart
    | where billable == false or IsBillable == true
    | summarize sum(Quantity));
let last24Velocity = toscalar(
    Usage
    | where TimeGenerated > ago(24h)
    | where billable == false or IsBillable == true
    | summarize MB = sum(Quantity)
    | extend v = MB / 24.0
    | project v);
let last1Velocity = toscalar(
    Usage
    | where TimeGenerated > ago(1h)
    | where billable == false or IsBillable == true
    | summarize sum(Quantity));
let observed = Usage
    | where TimeGenerated >= monthStart
    | where billable == false or IsBillable == true
    | summarize MB = sum(Quantity) by bin(TimeGenerated, 1h)
    | order by TimeGenerated asc
    | extend CumulativeGB = (row_cumsum(MB)) / 1024.0
    | project TimeGenerated, Series = 'Actual MTD (GB)', Value = CumulativeGB;
let futureHours = range h from 1 to toint(hoursRemaining) step 1
    | extend TimeGenerated = datetime_add('hour', h, now_);
let baseGB = mtdMB / 1024.0;
let proj24 = futureHours | extend Series = 'Projected from 24h velocity (GB)', Value = baseGB + ((h * last24Velocity) / 1024.0) | project TimeGenerated, Series, Value;
let proj1  = futureHours | extend Series = 'Projected from 1h velocity (GB)',  Value = baseGB + ((h * last1Velocity)  / 1024.0) | project TimeGenerated, Series, Value;
observed
| union proj24, proj1
| order by TimeGenerated asc
| render timechart

let billable = tobool('{BillableOnly}');
let last1 = Usage | where TimeGenerated > ago(1h) | where billable == false or IsBillable == true | summarize Last1hMB = sum(Quantity) by DataType;
let avg24 = Usage | where TimeGenerated > ago(24h) | where billable == false or IsBillable == true | summarize MB = sum(Quantity) by DataType | extend Avg24hMBph = MB / 24.0 | project DataType, Avg24hMBph;
last1
| join kind=fullouter avg24 on DataType
| extend DataType = coalesce(DataType, DataType1)
| project DataType, Last1hMB = coalesce(Last1hMB, 0.0), Avg24hMBph = coalesce(Avg24hMBph, 0.0)
| extend SpikeRatio = iif(Avg24hMBph == 0.0, 0.0, Last1hMB / Avg24hMBph)
| order by SpikeRatio desc
